1	import "server-only";
2	import { db } from "@/lib/db";
3	import type { TicketStatus } from "@prisma/client";
4	import type { ClaudeToolDef } from "@/lib/anthropic";
5	import { formatMoney, currentCurrency } from "@/lib/tax";
6	import { cardDisplayLabel, hasChargeableCard } from "@/lib/stripe-cards";
7	import { PLAN_CARDS } from "@/lib/kb-plans";
8	
9	// ---------------------------------------------------------------------------
10	// Per-customer, READ-ONLY diagnostic tools for the AI chat assistant.
11	//
12	// Every query in this file is scoped to the trusted `userId` FUNCTION ARGUMENT
13	// (the signed-in customer). The tool `input` is NEVER trusted to carry a userId
14	// or any ownership claim — it may only carry a service `id`, which is then
15	// re-checked to belong to `userId` before anything is returned. Nothing here
16	// writes, updates, or deletes; nothing here returns another user's row.
17	//
18	// Grounding (all confirmed against prisma/schema.prisma):
19	//   - Server            userId  — VPS, game servers (gamePlanId), NxCloud VMs
20	//   - HostingAccount    userId  — shared hosting
21	//   - Domain            userId
22	//   - EmailSubscription userId  — business email (Mailbox via subscription)
23	//   - Volume            userId  — block-storage add-on disks
24	//   - NxCloudInstance   userId  — managed Nextcloud
25	//   - Invoice           userId  — money in integer CENTS
26	//   - WalletTransaction userId  — wallet credits/debits in CENTS
27	//   - Ticket            userId  — support tickets
28	//   - User              balanceCents, signupCreditCents, card* mirror fields
29	//
30	// Money is stored as integer CENTS everywhere and displayed with formatMoney()
31	// in the account's configured display currency (default USD). Secrets
32	// (rootPassword*, *PasswordEnc, *PassEnc, tokens) are never read or returned;
33	// only the stored card brand/last4 are surfaced.
34	// ---------------------------------------------------------------------------
35	
36	/** Statuses treated as "still open" for a support ticket (i.e. not CLOSED). */
37	const OPEN_TICKET_STATUSES: TicketStatus[] = ["OPEN", "ANSWERED", "CUSTOMER_REPLY"];
38	
39	/** Map the User's stored card mirror fields onto the shared CardDisplay shape. */
40	function cardOf(user: {
41	  cardBrand: string | null;
42	  cardLast4: string | null;
43	  cardExpMonth: number | null;
44	  cardExpYear: number | null;
45	}) {
46	  return {
47	    brand: user.cardBrand,
48	    last4: user.cardLast4,
49	    expMonth: user.cardExpMonth,
50	    expYear: user.cardExpYear,
51	  };
52	}
53	
54	/** "2026-08-15" or "—" for a nullable date. */
55	function ymd(d: Date | null | undefined): string {
56	  return d ? d.toISOString().slice(0, 10) : "—";
57	}
58	
59	/** Short, model-friendly one-liner joiner. */
60	function lines(...parts: (string | false | null | undefined)[]): string {
61	  return parts.filter(Boolean).join("\n");
62	}
63	
64	/** Classify a Server row into a customer-facing service type. */
65	function serverType(s: { gamePlanId: string | null; nxcloudInstance: unknown | null }): string {
66	  if (s.nxcloudInstance) return "nxcloud";
67	  if (s.gamePlanId) return "game";
68	  return "vps";
69	}
