311	// ---------------------------------------------------------------------------
312	// Tool implementations (each scoped to userId)
313	// ---------------------------------------------------------------------------
314	
315	async function accountOverview(userId: string, money: (c: number) => string): Promise<string> {
316	  const now = new Date();
317	  const [user, servers, hosting, emailSubs, domains, volumes, openInvoices, openTickets] =
318	    await Promise.all([
319	      db.user.findUnique({
320	        where: { id: userId },
321	        select: {
322	          balanceCents: true,
323	          signupCreditCents: true,
324	          cardBrand: true,
325	          cardLast4: true,
326	          cardExpMonth: true,
327	          cardExpYear: true,
328	          stripeCustomerId: true,
329	          stripePaymentMethodId: true,
330	        },
331	      }),
332	      db.server.findMany({
333	        where: { userId, status: { not: "DELETING" } },
334	        select: { status: true, gamePlanId: true, nxcloudInstance: { select: { id: true } } },
335	      }),
336	      db.hostingAccount.groupBy({
337	        by: ["status"],
338	        where: { userId, status: { not: "DELETING" } },
339	        _count: true,
340	      }),
341	      db.emailSubscription.count({ where: { userId } }),
342	      db.domain.count({ where: { userId } }),
343	      db.volume.count({ where: { userId, status: { not: "DELETING" } } }),
344	      db.invoice.findMany({
345	        where: { userId, status: "OPEN" },
346	        select: { amountCents: true },
347	      }),
348	      db.ticket.count({ where: { userId, status: { in: OPEN_TICKET_STATUSES } } }),
349	    ]);
350	
351	  if (!user) return "Error: customer not found.";
352	
353	  // Server breakdown by type + status.
354	  const vps = servers.filter((s) => !s.gamePlanId && !s.nxcloudInstance);
355	  const game = servers.filter((s) => s.gamePlanId && !s.nxcloudInstance);
356	  const nxcloud = servers.filter((s) => s.nxcloudInstance);
357	  const statusMix = (rows: { status: string }[]) => {
358	    const m: Record<string, number> = {};
359	    for (const r of rows) m[r.status] = (m[r.status] ?? 0) + 1;
360	    return Object.entries(m)
361	      .map(([k, v]) => `${v} ${k}`)
362	      .join(", ");
363	  };
364	
365	  const svcLine = (label: string, rows: { status: string }[]) =>
366	    rows.length ? `${label}: ${rows.length} (${statusMix(rows)})` : null;
367	
368	  const hostingTotal = hosting.reduce((n, h) => n + h._count, 0);
369	  const hostingMix = hosting.map((h) => `${h._count} ${h.status}`).join(", ");
370	
371	  const cardLabel = cardDisplayLabel(cardOf(user));
372	  const overdueServers = await db.server.count({
373	    where: { userId, isFree: false, expiresAt: { lt: now }, status: { in: ["RUNNING", "STOPPED", "SUSPENDED"] } },
374	  });
375	
376	  const unpaidTotal = openInvoices.reduce((n, i) => n + i.amountCents, 0);
377	  const creditCents = user.balanceCents + user.signupCreditCents;
378	
379	  return lines(
380	    "ACCOUNT OVERVIEW",
381	    "Services:",
382	    svcLine("  VPS", vps),
383	    svcLine("  Game servers", game),
384	    svcLine("  Managed Nextcloud", nxcloud),
385	    hostingTotal ? `  Shared hosting: ${hostingTotal} (${hostingMix})` : null,
386	    emailSubs ? `  Business email: ${emailSubs} subscription(s)` : null,
387	    domains ? `  Domains: ${domains}` : null,
388	    volumes ? `  Storage volumes: ${volumes}` : null,
389	    !vps.length && !game.length && !nxcloud.length && !hostingTotal && !emailSubs && !domains && !volumes
390	      ? "  (no active services)"
391	      : null,
392	    "Billing:",
393	    `  Payment card on file: ${cardLabel ? cardLabel : "none"}${cardLabel && !hasChargeableCard(user) ? " (not currently chargeable)" : ""}`,
394	    `  Unpaid invoices: ${openInvoices.length}${openInvoices.length ? ` totaling ${money(unpaidTotal)}` : ""}`,
395	    overdueServers ? `  Past-due services in dunning: ${overdueServers}` : "  Past-due services: 0",
396	    `  Wallet balance / credit: ${money(creditCents)}`,
397	    `Open support tickets: ${openTickets}`,
398	  );
399	}
