401	async function listServices(userId: string): Promise<string> {
402	  const [servers, hosting, emailSubs, domains, volumes] = await Promise.all([
403	    db.server.findMany({
404	      where: { userId, status: { not: "DELETING" } },
405	      select: {
406	        id: true,
407	        name: true,
408	        label: true,
409	        status: true,
410	        expiresAt: true,
411	        gamePlanId: true,
412	        plan: { select: { name: true } },
413	        gamePlan: { select: { name: true, gameFamily: true } },
414	        nxcloudInstance: { select: { id: true, subdomain: true } },
415	      },
416	      orderBy: { createdAt: "asc" },
417	      take: 20,
418	    }),
419	    db.hostingAccount.findMany({
420	      where: { userId, status: { not: "DELETING" } },
421	      select: {
422	        id: true,
423	        primaryDomain: true,
424	        status: true,
425	        expiresAt: true,
426	        plan: { select: { name: true } },
427	      },
428	      orderBy: { createdAt: "asc" },
429	      take: 20,
430	    }),
431	    db.emailSubscription.findMany({
432	      where: { userId },
433	      select: {
434	        id: true,
435	        domainName: true,
436	        status: true,
437	        expiresAt: true,
438	        emailPlan: { select: { name: true } },
439	      },
440	      orderBy: { createdAt: "asc" },
441	      take: 20,
442	    }),
443	    db.domain.findMany({
444	      where: { userId },
445	      select: { id: true, name: true, status: true, expiresAt: true },
446	      orderBy: { createdAt: "asc" },
447	      take: 20,
448	    }),
449	    db.volume.findMany({
450	      where: { userId, status: { not: "DELETING" } },
451	      select: { id: true, name: true, status: true, sizeGB: true, expiresAt: true },
452	      orderBy: { createdAt: "asc" },
453	      take: 20,
454	    }),
455	  ]);
456	
457	  const out: string[] = [];
458	
459	  for (const s of servers) {
460	    const type = serverType(s);
461	    const label = s.label || s.name;
462	    const plan =
463	      type === "game"
464	        ? s.gamePlan?.name || `game (${s.gamePlan?.gameFamily ?? "?"})`
465	        : type === "nxcloud"
466	          ? `Nextcloud @ ${s.nxcloudInstance?.subdomain ?? "?"}`
467	          : s.plan?.name || "?";
468	    out.push(
469	      `[${s.id}] ${label} — type=${type} status=${s.status} plan="${plan}" renews=${ymd(s.expiresAt)}`,
470	    );
471	  }
472	  for (const h of hosting) {
473	    out.push(
474	      `[${h.id}] ${h.primaryDomain} — type=hosting status=${h.status} plan="${h.plan?.name ?? "?"}" renews=${ymd(h.expiresAt)}`,
475	    );
476	  }
477	  for (const e of emailSubs) {
478	    out.push(
479	      `[${e.id}] ${e.domainName} — type=email status=${e.status} plan="${e.emailPlan?.name ?? "?"}" renews=${ymd(e.expiresAt)}`,
480	    );
481	  }
482	  for (const d of domains) {
483	    out.push(`[${d.id}] ${d.name} — type=domain status=${d.status} expires=${ymd(d.expiresAt)}`);
484	  }
485	  for (const v of volumes) {
486	    out.push(
487	      `[${v.id}] ${v.name} — type=volume status=${v.status} size=${v.sizeGB}GB renews=${ymd(v.expiresAt)}`,
488	    );
489	  }
490	
491	  if (!out.length) return "This customer has no active services.";
492	  return lines("SERVICES (id — label — details):", ...out);
493	}
