495	async function getService(userId: string, input: unknown): Promise<string> {
496	  const id = typeof input === "object" && input && "id" in input ? String((input as { id: unknown }).id) : "";
497	  if (!id) return "Error: get_service requires an 'id'.";
498	
499	  // Every lookup is filtered by BOTH id AND userId, so a foreign id returns null.
500	  // --- Server (VPS / game / NxCloud VM) ---
501	  const server = await db.server.findFirst({
502	    where: { id, userId },
503	    select: {
504	      id: true,
505	      name: true,
506	      label: true,
507	      hostname: true,
508	      status: true,
509	      ipAddress: true,
510	      ipv6: true,
511	      gamePlanId: true,
512	      gameVariant: true,
513	      expiresAt: true,
514	      autoRenew: true,
515	      isFree: true,
516	      termMonths: true,
517	      extraDiskGB: true,
518	      suspendReason: true,
519	      provisionError: true,
520	      dunningStage: true,
521	      plan: { select: { name: true, cpuCores: true, ramMB: true, diskGB: true } },
522	      gamePlan: { select: { name: true, gameFamily: true, ramMB: true, slots: true } },
523	      nxcloudInstance: {
524	        select: { subdomain: true, status: true, version: true, storageQuotaMB: true, storageUsedMB: true },
525	      },
526	    },
527	  });
528	  if (server) {
529	    const type = serverType(server);
530	    const specs = server.plan
531	      ? `${server.plan.cpuCores} vCPU / ${server.plan.ramMB} MB RAM / ${server.plan.diskGB + (server.extraDiskGB ?? 0)} GB disk`
532	      : "?";
533	    return lines(
534	      `SERVICE ${server.id} (${type})`,
535	      `Label: ${server.label || server.name}`,
536	      `Status: ${server.status}${server.suspendReason ? ` (suspended: ${server.suspendReason})` : ""}`,
537	      `Hostname: ${server.hostname}`,
538	      server.ipAddress ? `IPv4: ${server.ipAddress}` : null,
539	      server.ipv6 ? `IPv6: ${server.ipv6}` : null,
540	      `Specs: ${specs}`,
541	      type === "game" && server.gamePlan
542	        ? `Game: ${server.gamePlan.gameFamily}${server.gameVariant ? ` (${server.gameVariant})` : ""}, ${server.gamePlan.slots ?? "?"} slots, plan "${server.gamePlan.name}"`
543	        : server.plan
544	          ? `Plan: ${server.plan.name}`
545	          : null,
546	      type === "nxcloud" && server.nxcloudInstance
547	        ? `Nextcloud: ${server.nxcloudInstance.subdomain} — ${server.nxcloudInstance.status}${server.nxcloudInstance.version ? `, v${server.nxcloudInstance.version}` : ""}, storage ${server.nxcloudInstance.storageUsedMB ?? "?"}/${server.nxcloudInstance.storageQuotaMB} MB`
548	        : null,
549	      `Billing: term=${server.termMonths}mo, autoRenew=${server.autoRenew}, free=${server.isFree}, renews=${ymd(server.expiresAt)}`,
