845	/** Open a new support ticket owned by this customer (the one write action). */
846	async function openTicket(userId: string, input: unknown): Promise<string> {
847	  const obj = (typeof input === "object" && input ? input : {}) as Record<string, unknown>;
848	  const subject = typeof obj.subject === "string" ? obj.subject.trim().slice(0, 200) : "";
849	  const body = typeof obj.body === "string" ? obj.body.trim().slice(0, 5000) : "";
850	  const priority = typeof obj.priority === "string" && TICKET_PRIORITIES.has(obj.priority.toUpperCase())
851	    ? (obj.priority.toUpperCase() as "LOW" | "NORMAL" | "HIGH" | "URGENT")
852	    : "NORMAL";
853	  if (!subject || !body) return "Error: open_support_ticket needs both a subject and a body.";
854	
855	  // Guard against duplicate/spam tickets from one chat: cap open tickets.
856	  const openCount = await db.ticket.count({
857	    where: { userId, status: { in: OPEN_TICKET_STATUSES } },
858	  });
859	  if (openCount >= 8) {
860	    return "This customer already has several open tickets — do not open another; point them to /dashboard/support to follow up on an existing one.";
861	  }
862	
863	  const ticket = await db.ticket.create({
864	    data: {
865	      userId,
866	      subject,
867	      priority,
868	      messages: { create: { authorId: userId, body, isStaff: false } },
869	    },
870	    select: { id: true },
871	  });
872	  return lines(
873	    `Opened support ticket [${ticket.id}] "${subject}" (priority ${priority}).`,
874	    "Tell the customer it's been created and they can follow it at /dashboard/support; the team will reply there and by email.",
875	  );
876	}
