958	/** Full-text search over the indexed help/FAQ/blog content (KbChunk). Kept local
959	 *  to avoid a cyclic import with lib/kb.ts. Returns snippets for the model to
960	 *  synthesize — the model must rewrite them, never paste them verbatim. */
961	async function searchHelp(input: unknown): Promise<string> {
962	  const query =
963	    typeof input === "object" && input && typeof (input as { query?: unknown }).query === "string"
964	      ? (input as { query: string }).query.trim()
965	      : "";
966	  if (query.length < 3) return "Provide a longer search query.";
967	  let rows: { source: string; title: string; url: string | null; snippet: string }[] = [];
968	  try {
969	    rows = await db.$queryRaw<{ source: string; title: string; url: string | null; snippet: string }[]>`
970	      SELECT source, title, url, snippet
971	      FROM "KbChunk"
972	      WHERE to_tsvector('english', title || ' ' || content) @@ websearch_to_tsquery('english', ${query})
973	      ORDER BY ts_rank(to_tsvector('english', title || ' ' || content),
974	                       websearch_to_tsquery('english', ${query})) DESC
975	      LIMIT 4`;
976	  } catch {
977	    return "Help search is unavailable right now — answer from the core knowledge base instead.";
978	  }
979	  if (!rows.length) return `No help articles matched "${query}". Answer from the core knowledge base, or offer to open a ticket.`;
980	  return lines(
981	    `HELP RESULTS for "${query}" (synthesize into your own words — do NOT paste verbatim, and only cite a link if it directly answers):`,
982	    ...rows.map((r) => `• ${r.title}${r.url ? ` (${r.url})` : ""}\n${r.snippet.slice(0, 400)}`),
983	  );
984	}
