123	/**
124	 * Generate a grounded, sales-oriented reply with Claude. Returns the text, or
125	 * null if no key is configured or the API call fails (caller then falls back to
126	 * the token-free retrieval answer so chat never breaks).
127	 */
128	export async function llmAnswer(args: {
129	  message: string;
130	  history: ClaudeMessage[];
131	  chunks: LlmChunk[];
132	  images?: LlmImage[];
133	  visitorName?: string | null;
134	  userId?: string | null;
135	}): Promise<LlmResult> {
136	  const key = await resolveBotKey();
137	  if (!key) return { ok: false, reason: "no_key" };
138	
139	  const accountAware = Boolean(args.userId);
140	  const uid = args.userId ?? null;
141	  const [model, coupon] = await Promise.all([
142	    getSetting("kb_bot_model", DEFAULT_BOT_MODEL),
143	    getSetting("kb_bot_coupon", ""),
144	  ]);
145	
146	  // A light pre-fetch of relevant help snippets seeds the first turn; the model
147	  // can also call search_help to dig deeper. Snippets are CONTEXT, never the
148	  // answer — the prompt forbids pasting them.
149	  const context = args.chunks.length
150	    ? "=== POSSIBLY-RELEVANT HELP SNIPPETS (context only — rewrite in your own words, never paste) ===\n" +
151	      args.chunks
152	        .map(
153	          (c) =>
154	            `• ${c.title}\n${c.snippet}${c.url ? `\n(link: ${c.url.startsWith("http") ? c.url : APP_URL + c.url})` : ""}`,
155	        )
156	        .join("\n\n")
157	    : "";
158	
159	  const base = buildSystem(coupon, args.visitorName ?? null, accountAware);
160	  const system = context ? `${base}\n\n${context}` : base;
161	
162	  // Current turn: images (if any) then the text. Empty text with an image still
163	  // needs a text block so the model knows what to do with the picture.
164	  const imgs = args.images ?? [];
165	  const currentContent: ClaudeContent = imgs.length
166	    ? [
167	        ...imgs.map((im) => ({
168	          type: "image" as const,
169	          source: { type: "base64" as const, media_type: im.mediaType, data: im.dataB64 },
170	        })),
171	        { type: "text" as const, text: args.message || "The visitor sent this image — take a look and help." },
172	      ]
173	    : args.message;
174	
175	  // Keep only the last few turns for context; the current message goes last.
176	  const trimmed = args.history.slice(-10);
177	  const messages: ClaudeMessage[] = [...trimmed, { role: "user", content: currentContent }];
178	
179	  const mdl = model.trim() || DEFAULT_BOT_MODEL;
180	
181	  // EVERY visitor gets the agentic loop now — signed-in customers with the full
182	  // account toolset, anonymous visitors with the public tools (plans, live
183	  // status, help search). The agent investigates with tools, then answers.
184	  try {
185	    const text = await askClaudeWithTools(key, {
186	      system,
187	      messages,
188	      tools: chatToolsFor(uid),
189	      execTool: (name, input) => runChatTool(uid, name, input),
190	      model: mdl,
191	      maxTokens: 800,
192	      timeoutMs: 30_000,
193	      maxRounds: 6,
194	    });
195	    const trimmedText = text.trim();
196	    if (!trimmedText) return { ok: false, reason: "empty" };
197	    return { ok: true, text: trimmedText };
198	  } catch (e) {
199	    // Surfaced to the caller so it can log a real degradation (bad/unfunded key,
200	    // API outage) AND degrade gracefully — NEVER silently fall to blog snippets.
201	    return { ok: false, reason: "error", detail: e instanceof Error ? e.message : "chat model error" };
202	  }
203	}
