19	/**
20	 * Front door to the Nxeon live-chat AGENT.
21	 *
22	 * The assistant is a Claude-powered agent (lib/kb-llm.ts) that reasons over the
23	 * full operator knowledge base and a suite of live tools — account lookups for
24	 * signed-in customers, plus public tools for plans, platform status, and help
25	 * search — and answers in its own words. There is NO keyword-retrieval fallback
26	 * that pastes blog snippets: retrieval only ever SEEDS the agent as context.
27	 *
28	 * When the model is genuinely unavailable (no key configured, or an API error)
29	 * the bot degrades GRACEFULLY to one warm, honest message that offers a human
30	 * follow-up — it never dumps an article link as "the answer". The failure reason
31	 * rides back on the result so the orchestrator (lib/kb-run.ts) can log a real
32	 * degradation for the operator instead of failing silently.
33	 *
34	 * Every call returns a typed `kind` so app/api/chat/route.ts can log it.
35	 * The index (KbChunk) is (re)built by lib/actions-kb.ts → reindexKb().
36	 */
37	
38	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
39	
40	export type ReplyKind = "smalltalk" | "handoff" | "offer" | "answer" | "degraded";
41	export type KbResult = {
42	  kind: ReplyKind;
43	  reply: string | null;
44	  matchedTitle?: string;
45	  /** Plan-card keys to render with this reply (resolved to cards in kb-run). */
46	  cardKeys?: string[];
47	  /** Present only when the model was unavailable, so the orchestrator can log a
48	   *  real degradation and alert the operator on a hard error (never silent). */
49	  llmFailure?: "no_key" | "error" | "over_cap";
50	};
51	
52	/** Warm, honest degradation — used ONLY when the model can't run (no key / API
53	 *  error / over the daily cap). Never a blog link; offers a human follow-up. */
54	function degradedReply(reason: "no_key" | "error" | "over_cap", name?: string | null): string {
55	  const who = name && name.trim() ? ` ${name.trim()}` : "";
56	  if (reason === "over_cap") {
57	    return `Thanks${who} — we're helping a lot of people in chat right now, so rather than rush you I want to make sure you get a solid answer. Drop your email with your question and the team will get right back to you (usually within a business day). In the meantime, ${APP_URL}/pricing has every plan and ${APP_URL}/help has quick guides.`;
58	  }
59	  return `Sorry${who} — I'm having a brief problem reaching my assistant just now. I don't want to guess at your answer. If you leave your email and what you need, the team will follow up quickly — or you can reach us any time at ${APP_URL}/contact. You can also check live status at ${APP_URL}/status.`;
60	}
