62	/** "which plan / what plan / recommend a plan / best plan / plan for X". */
63	export function planIntent(text: string): boolean {
64	  return /\b(which|what|best)\s+plan\b|\bplan\s+(should|would|do|for|to)\b|\brecommend\s+(a\s+)?plan\b|\bhelp me (choose|pick)\b|\bwhich (one|option|tier)\b/i.test(
65	    text,
66	  );
67	}
