69	type Row = { source: string; title: string; url: string | null; snippet: string; offer: boolean; rank: number };
70	
71	/** Explicit "get me a person". */
72	export function humanIntent(text: string): boolean {
73	  return /\b(human|agent|representative|real person|someone|a person|live (chat|agent|support)|talk to (a|your|the) (team|human|person|agent|rep)|speak (to|with))\b/i.test(text);
74	}
