76	/** "Do you have any deals / discounts / promos?" */
77	export function offerIntent(text: string): boolean {
78	  return /\b(deal|deals|discount|discounts|promo|promotion|coupon|voucher|offer|offers|sale|cheaper|save (money|some)|free month|free trial|any specials?)\b/i.test(text);
