81	/** Top knowledge-base matches. websearch_to_tsquery parses arbitrary user input
82	 *  safely, so this is injection- and crash-safe for anything a visitor types. */
83	export async function kbSearch(query: string, limit = 4): Promise<Row[]> {
84	  const q = query.trim();
85	  if (q.length < 3) return [];
86	  try {
87	    return await db.$queryRaw<Row[]>`
88	      SELECT source, title, url, snippet, "offer",
89	             ts_rank(to_tsvector('english', title || ' ' || content),
90	                     websearch_to_tsquery('english', ${q})) AS rank
91	      FROM "KbChunk"
92	      WHERE to_tsvector('english', title || ' ' || content) @@ websearch_to_tsquery('english', ${q})
93	      ORDER BY rank DESC
94	      LIMIT ${limit}`;
95	  } catch {
96	    return [];
97	  }
98	}
