100	/**
101	 * Decide how the assistant should respond to a visitor message. Priority:
102	 * explicit human hand-off → the Claude agent (tools + full KB, for everyone) →
103	 * graceful degradation if the model can't run. There is no keyword-retrieval
104	 * fallback and no canned "clarifier" — the agent handles greetings, questions,
105	 * and everything in between. Always returns a `kind` so the caller can log
106	 * coverage. `history` is the prior conversation (oldest→newest) for context.
107	 */
108	export async function kbAnswer(message: string, opts: KbAnswerOpts = {}): Promise<KbResult> {
109	  const history = opts.history ?? [];
110	
111	  // 1. Explicit "get me a person" — hand-off (kb-run turns this into the live
112	  //    escalation + email flow). No tokens spent.
113	  if (humanIntent(message)) {
114	    return {
115	      kind: "handoff",
116	      reply:
117	        "No problem — I'll connect you with our team. Someone will be with you shortly. Feel free to add any details in the meantime.",
118	    };
119	  }
120	
121	  // 2. Over the daily cost cap → degrade gracefully (no model call, no snippet).
122	  if (opts.noLlm) {
123	    return {
124	      kind: "degraded",
125	      reply: degradedReply("over_cap", opts.visitorName),
126	      llmFailure: "over_cap",
127	    };
128	  }
129	
130	  // 3. Seed a little help context (cheap FTS), then run the agent for EVERYONE.
131	  //    The agent investigates with its tools and answers in its own words; plan
132	  //    cards ride back via a hidden [[cards: …]] directive parsed in kb-run.
133	  const rows = await kbSearch(message);
134	  const chunks = rows.map((r) => ({ title: r.title, snippet: r.snippet, url: r.url }));
135	  const res = await llmAnswer({
136	    message,
137	    history,
138	    chunks,
139	    images: opts.images,
140	    visitorName: opts.visitorName ?? null,
141	    userId: opts.userId ?? null,
142	  });
143	
144	  if (res.ok) {
145	    return {
146	      kind: offerIntent(message) ? "offer" : "answer",
147	      reply: res.text,
148	      matchedTitle: rows[0]?.title,
149	    };
150	  }
151	
152	  // 4. Model unavailable. NEVER paste a blog snippet. A plain greeting still gets
153	  //    a warm hello; anything else gets an honest "let me get the team" message.
154	  //    The failure reason rides back so kb-run logs a real degradation.
155	  if (res.reason === "no_key" && greetingIntent(message)) {
156	    return { kind: "smalltalk", reply: greetingReply(opts.visitorName) };
157	  }
158	  return {
159	    kind: "degraded",
160	    reply: degradedReply(res.reason === "error" ? "error" : "no_key", opts.visitorName),
161	    llmFailure: res.reason === "error" ? "error" : "no_key",
162	  };
163	}
