41	/** Extract a hidden `[[cards: key1, key2]]` directive from a bot reply, returning
42	 *  the visible body (directive stripped) and the card keys. */
43	function parseCardDirective(reply: string): { body: string; keys: string[] } {
44	  const m = reply.match(/\[\[\s*cards?\s*:\s*([^\]]+)\]\]/i);
45	  if (!m) return { body: reply, keys: [] };
46	  const keys = m[1]
47	    .split(",")
48	    .map((s) => s.trim())
49	    .filter(Boolean);
50	  const body = reply.replace(m[0], "").replace(/\n{3,}/g, "\n\n").trim();
51	  return { body, keys };
