111	/**
112	 * If a conversation is waiting on a human and the window has elapsed with no
113	 * agent, post the "no agents available" fallback and clear the waiting state.
114	 * Atomic (updateMany claim) so concurrent polls can't double-post. Safe to call
115	 * on every message and every GET poll.
116	 */
117	export async function checkEscalationTimeout(conversationId: string): Promise<void> {
118	  try {
119	    const convo = await db.chatConversation.findUnique({
120	      where: { id: conversationId },
121	      select: { id: true, botEscalatedAt: true, assignedToId: true },
122	    });
123	    if (!convo?.botEscalatedAt) return;
124	
125	    // An agent joined (assigned or replied) — drop the waiting state, no fallback.
126	    const agentReplies = await db.chatMessage.count({
127	      where: { conversationId, sender: "agent" },
128	    });
129	    if (agentReplies > 0 || convo.assignedToId) {
130	      await db.chatConversation.updateMany({
131	        where: { id: conversationId, botEscalatedAt: { not: null } },
132	        data: { botEscalatedAt: null },
133	      });
134	      return;
135	    }
136	
137	    const windowSec = await getSettingInt("kb_bot_window_sec", 180);
138	    const threshold = new Date(Date.now() - windowSec * 1000);
139	    // Claim the timeout: only one caller wins, and only once the window passed.
140	    const claim = await db.chatConversation.updateMany({
141	      where: { id: conversationId, botEscalatedAt: { not: null, lte: threshold }, assignedToId: null },
142	      data: { botEscalatedAt: null },
143	    });
144	    if (claim.count !== 1) return;
145	
146	    await db.chatMessage.create({
147	      data: { conversationId, sender: "bot", body: NO_AGENT_MSG },
148	    });
149	  } catch {
150	    /* non-essential */
151	  }
152	}
