155	 * Evaluate the assistant for a just-received visitor message. Creates a bot
156	 * reply (or runs the handoff flow) when appropriate. `images` are the base64
157	 * blocks for an image the visitor just sent (upload path), if any.
158	 */
159	export async function runAssistant(args: {
160	  conversationId: string;
161	  visitorId: string;
162	  currentBody: string;
163	  images?: LlmImage[];
164	}): Promise<void> {
165	  try {
166	    if ((await getSetting("kb_bot_enabled", "false")) !== "true") return;
167	
168	    const convo = await db.chatConversation.findUnique({
169	      where: { id: args.conversationId },
170	      select: {
171	        id: true,
172	        visitorId: true,
173	        userId: true,
174	        name: true,
175	        email: true,
176	        assignedToId: true,
177	        botEscalatedAt: true,
178	        messages: { orderBy: { createdAt: "asc" }, select: { sender: true, body: true } },
179	      },
180	    });
181	    if (!convo) return;
182	
183	    // Never talk over a human: silent once an agent replied or was assigned.
184	    const agentReplied = convo.messages.some((m) => m.sender === "agent");
185	    if (agentReplied || convo.assignedToId) return;
186	
187	    // Already waiting on a live agent — stay quiet; just check the timeout.
188	    if (convo.botEscalatedAt) {
189	      await checkEscalationTimeout(convo.id);
190	      return;
191	    }
192	
193	    // Guardrail: per-conversation reply cap → escalate instead of looping.
194	    const botCount = convo.messages.filter((m) => m.sender === "bot").length;
195	    const maxReplies = await getSettingInt("kb_bot_max_replies", 16);
196	    if (maxReplies > 0 && botCount >= maxReplies) {
197	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
198	      return;
199	    }
200	
201	    // Guardrail: platform-wide daily reply cap (soft cost ceiling). Over it, we
202	    // still answer — just from the token-free retrieval path (no paid call).
203	    let overDaily = false;
204	    const dailyCap = await getSettingInt("kb_bot_daily_cap", 1000);
205	    if (dailyCap > 0) {
206	      const since = new Date();
207	      since.setHours(0, 0, 0, 0);
208	      const used = await db.kbBotLog.count({
209	        where: { createdAt: { gte: since }, kind: { in: ["answer", "offer"] } },
210	      });
211	      overDaily = used >= dailyCap;
212	    }
213	
214	    const history = toHistory(convo.messages.slice(0, -1));
215	    const result = await kbAnswer(args.currentBody, {
216	      history,
217	      images: args.images,
218	      visitorName: firstName(convo.name),
219	      userId: convo.userId,
220	      noLlm: overDaily,
221	    });
222	
223	    // A live agent is ONLY brought in when the visitor explicitly asks for one
224	    // (humanIntent → kind "handoff"). The bot never offers or escalates on its own.
225	    if (result.kind === "handoff") {
226	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
227	      return;
228	    }
229	
230	    if (result.reply) {
231	      // Resolve any plan cards to render with this reply: the LLM signals them
232	      // with a hidden [[cards: key1, key2]] directive; the retrieval fallback
233	      // supplies result.cardKeys. Cards are looked up from the real catalog, so
234	      // the model can only ever pick keys — prices/features are never invented.
235	      const parsed = parseCardDirective(result.reply);
236	      const keys = [...(result.cardKeys ?? []), ...parsed.keys];
237	      const cards = keys.length ? getPlanCards(keys) : [];
238	      await db.chatMessage.create({
239	        data: {
240	          conversationId: convo.id,
241	          sender: "bot",
242	          body: parsed.body,
243	          cardsJson: cards.length ? JSON.stringify(cards) : null,
244	        },
245	      });
246	    }
247	    // Log coverage. A HARD model failure (bad/unfunded key, API outage) is logged
248	    // as "llm_error" — distinct from an expected "degraded"/over-cap — so the
249	    // admin KB dashboard shows the bot is broken instead of it failing silently.
250	    await db.kbBotLog
251	      .create({
252	        data: {
253	          visitorId: args.visitorId,
254	          conversationId: convo.id,
255	          question: args.currentBody.slice(0, 500),
256	          kind: result.llmFailure === "error" ? "llm_error" : result.kind,
257	          matchedTitle: result.matchedTitle ?? null,
258	        },
259	      })
260	      .catch(() => {});
261	  } catch {
262	    /* assistant is non-essential — never fail the visitor's message on it */
263	  }
264	}
