18	function stripMd(md: string): string {
19	  return md
20	    .replace(/```[\s\S]*?```/g, " ")
21	    .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
22	    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
23	    .replace(/[#>*_`~|-]+/g, " ")
24	    .replace(/\s+/g, " ")
25	    .trim();
26	}
