28	export async function reindexKb(): Promise<{ ok?: boolean; error?: string; count?: number }> {
29	  await requireArea("platform");
30	
31	  const faqRows = KB_FAQ.map((f, i) => ({
32	    source: "faq",
33	    refId: `faq-${i}`,
34	    title: f.q,
35	    url: f.url ?? null,
36	    content: `${f.q}\n${f.a}`,
37	    snippet: f.a,
38	    category: f.category ?? null,
39	    offer: f.offer ?? false,
40	  }));
41	
42	  const posts = await db.blogPost.findMany({
43	    where: { published: true },
44	    select: { slug: true, title: true, excerpt: true, body: true, category: true },
45	  });
46	  const blogRows = posts.map((p) => {
47	    const bodyText = stripMd(p.body || "");
48	    const snip = (p.excerpt?.trim() || bodyText).slice(0, 340).trim();
49	    return {
50	      source: "blog",
51	      refId: p.slug,
52	      title: p.title,
53	      url: `/blog/${p.slug}`,
54	      content: `${p.title}\n${p.excerpt ?? ""}\n${bodyText}`.slice(0, 8000),
55	      snippet: snip,
56	      category: p.category ?? "Guides",
57	      offer: false,
58	    };
59	  });
60	
61	  // Approved learnings (from the review-gated learning loop) become part of the
62	  // KB so they survive reindex and keep improving the assistant's answers.
63	  const learned = await db.kbSuggestion.findMany({
64	    where: { status: "approved" },
65	    select: { id: true, question: true, answer: true, category: true },
66	  });
67	  const learnedRows = learned.map((s) => ({
68	    source: "learned",
69	    refId: `learned-${s.id}`,
70	    title: s.question,
71	    url: null,
72	    content: `${s.question}\n${s.answer}`,
73	    snippet: s.answer.slice(0, 340),
74	    category: s.category ?? "Learned",
75	    offer: false,
76	  }));
77	
78	  const rows = [...faqRows, ...blogRows, ...learnedRows];
79	  try {
80	    await db.$transaction([
81	      db.kbChunk.deleteMany({}),
82	      db.kbChunk.createMany({ data: rows }),
83	    ]);
84	    try {
85	      await db.$executeRawUnsafe(
86	        `CREATE INDEX IF NOT EXISTS kbchunk_fts_idx ON "KbChunk" USING gin (to_tsvector('english', title || ' ' || content))`,
87	      );
88	    } catch { /* index is an optimization, not a requirement */ }
89	  } catch (e) {
90	    return { error: e instanceof Error ? e.message : "Reindex failed." };
91	  }
92	
93	  return { ok: true, count: rows.length };
94	}
