109	/** Recent bot evaluations + a breakdown by kind + the top UNANSWERED questions
110	 *  (what to add to the FAQ next). All admin-gated. */
111	export async function kbActivity(): Promise<{
112	  recent: BotLogRow[];
113	  totals: Record<string, number>;
114	  answeredRate: number;
115	  unanswered: { question: string; count: number }[];
116	  /** Count of HARD model failures (bad/unfunded key, API outage) in the last 24h.
117	   *  When > 0 the bot is degraded — the admin card shows a red warning so a dead
118	   *  key is caught immediately instead of silently degrading for a day. */
119	  llmErrors24h: number;
120	}> {
121	  await requireArea("platform");
122	
123	  const since24h = new Date(Date.now() - 24 * 60 * 60 * 1000);
124	  const llmErrors24h = await db.kbBotLog.count({
125	    where: { kind: "llm_error", createdAt: { gte: since24h } },
126	  });
127	
128	  const recentRaw = await db.kbBotLog.findMany({
129	    orderBy: { createdAt: "desc" },
130	    take: 40,
131	    select: { id: true, question: true, kind: true, matchedTitle: true, createdAt: true },
132	  });
133	  const recent = recentRaw.map((r) => ({
134	    id: r.id,
135	    question: r.question,
136	    kind: r.kind,
137	    matchedTitle: r.matchedTitle,
138	    createdAt: r.createdAt.toISOString(),
139	  }));
140	
141	  const grouped = await db.kbBotLog.groupBy({ by: ["kind"], _count: { _all: true } });
142	  const totals: Record<string, number> = {};
143	  for (const g of grouped) totals[g.kind] = g._count._all;
144	  const all = Object.values(totals).reduce((a, b) => a + b, 0);
145	  const answered = (totals.answer ?? 0) + (totals.offer ?? 0) + (totals.smalltalk ?? 0) + (totals.handoff ?? 0);
146	  const answeredRate = all ? Math.round((answered / all) * 100) : 0;
147	
148	  // Top unanswered questions — the coverage gaps to fill in the FAQ.
149	  const gaps = await db.$queryRaw<{ question: string; count: bigint }[]>`
150	    SELECT lower(trim(question)) AS question, COUNT(*) AS count
151	    FROM "KbBotLog"
152	    WHERE kind = 'none'
153	    GROUP BY lower(trim(question))
154	    ORDER BY count DESC
155	    LIMIT 15`;
156	  const unanswered = gaps.map((g) => ({ question: g.question, count: Number(g.count) }));
157	
158	  return { recent, totals, answeredRate, unanswered, llmErrors24h };
159	}
