241	  await requireArea("platform");
242	  const enc = await getSetting("kb_bot_api_key", "");
243	  const key = decryptSecret(enc || null)?.trim() || process.env.ANTHROPIC_API_KEY?.trim() || null;
244	  if (!key) return { ok: false, error: "No API key set." };
245	  const model = (await getSetting("kb_bot_model", "claude-haiku-4-5")).trim() || "claude-haiku-4-5";
246	  try {
247	    const res = await fetch("https://api.anthropic.com/v1/messages", {
248	      method: "POST",
249	      headers: { "content-type": "application/json", "x-api-key": key, "anthropic-version": "2023-06-01" },
250	      body: JSON.stringify({ model, max_tokens: 8, messages: [{ role: "user", content: "ping" }] }),
251	    });
252	    if (res.ok) return { ok: true, model };
253	    const t = await res.text().catch(() => "");
254	    let msg = `HTTP ${res.status}`;
255	    try {
256	      const j = JSON.parse(t) as { error?: { message?: string } };
257	      if (j?.error?.message) msg = j.error.message;
258	    } catch {
259	      /* keep the HTTP status */
260	    }
261	    return { ok: false, status: res.status, error: msg, model };
262	  } catch (e) {
263	    return { ok: false, error: e instanceof Error ? e.message : "Network error (egress blocked?)", model };
