289	/** Draft answers for the top questions the assistant couldn't handle. Uses the
290	 *  configured key to draft (grounded on the KB); if none, it still files the gap
291	 *  with a blank answer for you to write. Nothing goes live without approval. */
292	export async function generateSuggestions(): Promise<{ ok?: boolean; created?: number; error?: string }> {
293	  await requireArea("platform");
294	
295	  const gaps = await db.$queryRaw<{ question: string }[]>`
296	    SELECT lower(trim(question)) AS question
297	    FROM "KbBotLog" WHERE kind = 'none'
298	    GROUP BY lower(trim(question))
299	    ORDER BY COUNT(*) DESC
300	    LIMIT 12`;
301	  if (gaps.length === 0) return { ok: true, created: 0 };
302	
303	  const existing = new Set(
304	    (await db.kbSuggestion.findMany({ select: { question: true } })).map((s) =>
305	      s.question.toLowerCase().trim(),
306	    ),
307	  );
308	  const fresh = gaps
309	    .map((g) => g.question)
310	    .filter((q) => q && q.length > 2 && !existing.has(q))
311	    .slice(0, 8);
312	  if (fresh.length === 0) return { ok: true, created: 0 };
313	
314	  const enc = await getSetting("kb_bot_api_key", "");
315	  const key = decryptSecret(enc || null)?.trim() || process.env.ANTHROPIC_API_KEY?.trim() || null;
316	  const model = (await getSetting("kb_bot_model", "claude-haiku-4-5")).trim() || "claude-haiku-4-5";
317	
318	  let system = "";
319	  if (key) {
320	    try {
321	      const { KB_SYSTEM } = await import("./kb-system");
322	      system =
323	        "You write short, accurate FAQ answers for Nxeon's help center, grounded ONLY in the knowledge base below. If the KB genuinely doesn't cover it, reply with exactly NO_ANSWER. 1-3 sentences, friendly and factual. Never invent prices, plans, or specs.\n\n=== KNOWLEDGE BASE ===\n" +
324	        KB_SYSTEM;
325	    } catch {
326	      /* KB unavailable — fall through to blank answers */
327	    }
328	  }
329	
330	  let created = 0;
331	  for (const q of fresh) {
332	    let answer = "";
333	    if (key && system) {
334	      try {
335	        const draft = await askClaude(
336	          key,
337	          [{ role: "user", content: `A visitor asked: "${q}". Write the help-center answer.` }],
338	          system,
339	          { model, maxTokens: 300, timeoutMs: 20_000 },
340	        );
341	        if (draft && !/NO_ANSWER/i.test(draft)) answer = draft.trim();
342	      } catch {
343	        /* leave blank for manual authoring */
344	      }
345	    }
346	    await db.kbSuggestion.create({
347	      data: { question: q.slice(0, 300), answer: answer.slice(0, 2000), source: "gap" },
348	    });
349	    created++;
350	  }
351	  return { ok: true, created };
352	}
