372	/** Approve a suggestion → it becomes a live "learned" KB entry (and survives
373	 *  reindex). Optionally pass an edited answer. Admin-gated. */
374	export async function approveSuggestion(
375	  id: string,
376	  answer?: string,
377	): Promise<{ ok?: boolean; error?: string }> {
378	  await requireArea("platform");
379	  const s = await db.kbSuggestion.findUnique({ where: { id } });
380	  if (!s) return { error: "Not found." };
381	  const finalAnswer = (answer ?? s.answer).trim();
382	  if (!finalAnswer) return { error: "Add an answer before approving." };
383	  try {
384	    await db.$transaction([
385	      db.kbSuggestion.update({ where: { id }, data: { status: "approved", answer: finalAnswer } }),
386	      db.kbChunk.create({
387	        data: {
388	          source: "learned",
389	          refId: `learned-${id}`,
390	          title: s.question,
391	          url: null,
392	          content: `${s.question}\n${finalAnswer}`,
393	          snippet: finalAnswer.slice(0, 340),
394	          category: s.category ?? "Learned",
395	          offer: false,
396	        },
397	      }),
398	    ]);
399	    return { ok: true };
400	  } catch (e) {
401	    return { error: e instanceof Error ? e.message : "Approve failed." };
402	  }
