export type ClaudeToolDef = {
  name: string;
  description: string;
  input_schema: Record<string, unknown>;
};

type AnyBlock = { type: string; text?: string; id?: string; name?: string; input?: unknown };
type AnyMsg = { role: "user" | "assistant"; content: unknown };

/**
 * Agentic Messages call: give the model tools, run the look-up→reason loop
 * (execute each tool_use, feed the result back) until it produces a final
 * answer or the round cap is hit. `execTool` runs YOUR scoped, read-only tool
 * and returns a string for the model. Returns the model's final text.
 */
export async function askClaudeWithTools(
  apiKey: string,
  opts: {
    system: string;
    messages: ClaudeMessage[];
    tools: ClaudeToolDef[];
    execTool: (name: string, input: unknown) => Promise<string>;
    model?: string;
    maxTokens?: number;
    timeoutMs?: number;
    maxRounds?: number;
  },
): Promise<string> {
  if (!apiKey) throw new Error("No Anthropic API key available");
  const msgs: AnyMsg[] = [...(opts.messages as AnyMsg[])];
  const rounds = opts.maxRounds ?? 4;

  for (let i = 0; i < rounds; i++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? 26_000);
    let res: Response;
    try {
      res = await fetch(ANTHROPIC_URL, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-api-key": apiKey,
          "anthropic-version": "2023-06-01",
        },
        body: JSON.stringify({
          model: opts.model ?? MODEL,
          max_tokens: opts.maxTokens ?? 600,
          system: opts.system,
          tools: opts.tools,
          messages: msgs,
        }),
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timer);
    }
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      throw new Error(`Anthropic API ${res.status}: ${body.slice(0, 500)}`);
    }
    const data = (await res.json()) as { content?: AnyBlock[]; stop_reason?: string };
    const content = data.content ?? [];

    if (data.stop_reason !== "tool_use") {
      return content
        .filter((b) => b.type === "text" && typeof b.text === "string")
        .map((b) => b.text as string)
        .join("")
        .trim();
    }

    // Execute every requested tool, then feed all results back in one user turn.
    msgs.push({ role: "assistant", content });
    const toolResults: Array<{ type: "tool_result"; tool_use_id: string; content: string }> = [];
    for (const block of content) {
      if (block.type === "tool_use" && block.id && block.name) {
        let out: string;
        try {
          out = await opts.execTool(block.name, block.input);
        } catch (e) {
