/**
 * Shared source-reading helpers for the structural tripwire suites.
 *
 * NOT named `*.test.ts` on purpose: `npm test` globs `test/*.test.ts`, so this
 * module is imported, never executed as a suite. It used to live inside
 * customer-actions-guards.test.ts and be imported from there, which made every
 * assertion in that file run a second time under the importing suite's name.
 */

/**
 * Blank out the CONTENTS of every string / template literal, on top of
 * `stripComments`. Quotes and backticks are kept so the token stream still
 * parses by eye; only what is between them is erased.
 *
 * `${…}` interpolations inside a template literal are KEPT, because they are
 * executable code, not string content. Erasing them would hide exactly the
 * detail some tripwires exist to check — a rate-limit bucket keyed on
 * `` `x:${user.id}` `` versus one keyed on `` `x:${clientIp}` `` is the
 * difference between limiting an account and limiting a forgeable header, and
 * both collapse to the same blank if the interpolation goes with the text.
 *
 * WHY BOTH ARE NEEDED. `stripComments` deliberately preserves literals (there is
 * a test asserting exactly that), because plenty of tripwires need to read a
 * literal — "is MAIL_HOST still `mail.nxeon.cloud`?". But a tripwire asserting a
 * CALL is present must not match a mention of that call inside a string, and
 * this repo is full of such mentions: error copy, audit-log `action` values, and
 * doc strings that quote the very function being checked. Comments alone are not
 * enough here — `"Couldn't apply forwarding on the mail server"` and
 * `detail: "mailbox.suspend"` are executable code, and a naive grep is happy
 * with either.
 *
 * So: use `stripComments` when the assertion is ABOUT a literal's value, and
 * this when the assertion is about code SHAPE.
 */
export function stripCommentsAndStrings(src: string): string {
  const s = stripComments(src);
  const n = s.length;
  let out = "";
  let i = 0;

  /** Consume the body of a literal opened by `quote` at `i`, appending to `out`. */
  const literal = (quote: string) => {
    out += quote;
    i++;
    while (i < n) {
      const c = s[i];
      if (c === "\\") {
        // Escapes are consumed whole so `\"` never closes the literal.
        i += 2;
        continue;
      }
      if (c === quote) break;
      // Newlines survive so line numbers in a failure still line up.
      if (c === "\n") out += "\n";
      if (quote === "`" && c === "$" && s[i + 1] === "{") {
        // An interpolation is code. Copy it verbatim, tracking brace depth so a
        // nested object/template inside it doesn't end it early.
        out += "${";
        i += 2;
        let depth = 1;
        while (i < n && depth > 0) {
          const d = s[i];
          if (d === "{") depth++;
          else if (d === "}") depth--;
          else if (d === '"' || d === "'" || d === "`") {
            literal(d); // nested literal — its own contents get blanked
            continue;
          }
          if (depth > 0) out += d;
          i++;
        }
        out += "}";
        continue;
      }
      i++;
    }
    if (i < n) out += s[i];
    i++;
  };

  // A `/`-delimited regex literal may contain quote characters inside a character
  // class — e.g. `/[^"'<>]+/`. Without regex awareness the loop below sees that
  // `'` as the start of a string and swallows the rest of the file to the next
  // quote, silently returning near-empty source. That made every tripwire run over
  // a file containing such a regex VACUOUS — it happened to `lib/email-render.ts`,
  // whose `SECRET_QUERY_PARAM` is exactly `/…[^&"'<>\s#]+/gi`, blanking the whole
  // module so a security assertion passed against nothing. `stripComments` already
  // skips regexes correctly (tracking `[` … `]`); this pass now does too.
  const REGEX_PRECEDERS = new Set([
    "", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n",
  ]);
  let prev = "";
  const consumeRegex = () => {
    out += s[i]; // opening /
    i++;
    let inClass = false;
    for (; i < n; i++) {
      const r = s[i];
      out += r;
      if (r === "\\") {
        if (i + 1 < n) out += s[i + 1];
        i++;
        continue;
      }
      if (r === "[") inClass = true;
      else if (r === "]") inClass = false;
      else if (r === "/" && !inClass) { i++; break; }
      else if (r === "\n") { i++; break; } // unterminated — stop rather than run away
    }
    prev = "/";
  };

  while (i < n) {
    const c = s[i];
    if (c === '"' || c === "'" || c === "`") {
      literal(c);
      prev = c;
      continue;
    }
    // `//` and `/*` were already removed by stripComments, so a `/` after a
    // regex-preceding token here is a genuine literal, not division.
    if (c === "/" && (REGEX_PRECEDERS.has(prev) || /\b(return|typeof|case|in|of|new|do|else|yield|await)\s*$/.test(out))) {
      consumeRegex();
      continue;
    }
    out += c;
    if (!/\s/.test(c) || c === "\n") prev = c;
    i++;
  }
  return out;
}

export function stripComments(src: string): string {
  let out = "";
  let i = 0;
  const n = src.length;
  let quote: string | null = null;
  /** Last non-whitespace character emitted — decides `/` = regex vs. division. */
  let prev = "";

  /** Positions where a `/` begins a regex literal rather than a division. */
  const REGEX_PRECEDERS = new Set(["", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n"]);
  const REGEX_KEYWORDS = /\b(return|typeof|case|in|of|delete|void|instanceof|new|do|else|yield|await)\s*$/;

  while (i < n) {
    const c = src[i];
    const next = src[i + 1];

    if (quote) {
      out += c;
      if (c === "\\") {
        // Escape: copy the escaped character too, so `\"` never closes a string.
        if (i + 1 < n) out += src[i + 1];
        i += 2;
        continue;
      }
      if (c === quote) quote = null;
      i++;
      continue;
    }

    if (c === '"' || c === "'" || c === "`") {
      quote = c;
      out += c;
      prev = c;
      i++;
      continue;
    }

    // `//` and `/*` are ALWAYS comments in valid JS — a regex literal cannot
    // begin with an unescaped `/` or a `*`. So comments win unconditionally, and
    // the regex branch below only ever sees a genuine literal.
    if (c === "/" && next === "/") {
      while (i < n && src[i] !== "\n") i++;
      out += " ";
      continue;
    }
    if (c === "/" && next === "*") {
      i += 2;
      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i++;
      i += 2;
      out += " ";
      continue;
    }

    // A regex literal must be consumed whole, or its escaped slashes (`\/\/` in
    // `/^https?:\/\//`) look like the start of a comment and eat the rest of the
    // line — silently deleting real code from everything asserted below.
    if (c === "/" && (REGEX_PRECEDERS.has(prev) || REGEX_KEYWORDS.test(out))) {
      out += c;
      i++;
      let inClass = false;
      for (; i < n; i++) {
        const r = src[i];
        out += r;
        if (r === "\\") {
          if (i + 1 < n) out += src[i + 1];
          i++;
          continue;
        }
        if (r === "[") inClass = true;
        else if (r === "]") inClass = false;
        else if (r === "/" && !inClass) {
          i++;
          break;
        } else if (r === "\n") {
          // Not a regex after all (unterminated) — stop rather than run away.
          i++;
          break;
        }
      }
      prev = "/";
      continue;
    }

    out += c;
    if (!/\s/.test(c) || c === "\n") prev = c;
    i++;
  }
  return out;
}
