import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/* ------------------------------------------------------------------ *
 * Live-chat AGENT tool routing + graceful degradation.
 *
 * The reworked assistant runs an agentic tool loop for EVERY visitor
 * (lib/kb-tools.ts): PUBLIC tools for anyone, account tools only for a
 * signed-in customer. When the model can't run at all, the front door
 * (lib/kb.ts → degradedReply) must degrade to ONE warm, honest message
 * that offers a human follow-up — never a dumped blog link.
 *
 * These are behavioural checks, run against the real modules. The lib
 * files open with `import "server-only"`, a build-time no-op that isn't
 * installed for a bare `tsx` run, so we first drop the same empty shim
 * Next.js provides on the server. It stays hermetic: get_plans and the
 * sign-in guard are pure (no DB), and degradedReply is a pure string.
 * ------------------------------------------------------------------ */

// `import "server-only"` resolves to an empty module on the server. Provide it
// (idempotently) BEFORE the dynamic imports below so the modules load under tsx.
const shimDir = join(import.meta.dirname, "..", "node_modules", "server-only");
if (!existsSync(join(shimDir, "index.js"))) {
  mkdirSync(shimDir, { recursive: true });
  writeFileSync(
    join(shimDir, "package.json"),
    '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n',
  );
  writeFileSync(join(shimDir, "index.js"), "module.exports = {};\n");
}

const { runChatTool, runPublicTool } = await import("../lib/kb-tools.ts");
const { degradedReply } = await import("../lib/kb.ts");

test("an account tool without a signed-in user is a gentle sign-in ask, never a throw", async () => {
  // list_services is an ACCOUNT tool — with no userId it must NOT hit the DB and
  // must NOT throw; it returns a string steering the visitor to sign in.
  const r = await runChatTool(null, "list_services", {});
  assert.equal(typeof r, "string");
  assert.ok(r.length > 0);
  assert.match(r, /sign in/i);
  assert.match(r, /\/login/); // points them at the real login route
});

test("public tools route WITHOUT a user (no sign-in guard)", async () => {
  // get_plans is pure (reads the static PLAN_CARDS catalog) — a clean check that
  // an anonymous visitor is served the public path, not the account guard.
  const plans = await runPublicTool("get_plans", { product: "vps" });
  assert.equal(typeof plans, "string");
  assert.match(plans, /PLAN CATALOG/);
  assert.doesNotMatch(plans, /sign in/i);

  // runChatTool must also dispatch a PUBLIC tool name for a null user rather than
  // fall into the account sign-in guard.
  const status = await runChatTool(null, "check_platform_status", {});
  assert.equal(typeof status, "string");
  assert.doesNotMatch(status, /sign in/i);
});

test("an unknown tool name is a safe error string, never a throw", async () => {
  const r = await runPublicTool("does_not_exist", {});
  assert.equal(typeof r, "string");
  assert.match(r, /unknown tool/i);
});

test("degradedReply offers a human/contact path and never dumps a blog link", () => {
  for (const reason of ["no_key", "error", "over_cap"] as const) {
    const r = degradedReply(reason, "Sam");
    assert.ok(r.trim().length > 20, `${reason} must be a real message`);
    // The whole point of the rework: no blog-snippet/article link as "the answer".
    assert.doesNotMatch(r, /\/blog\//i, `${reason} must not link a blog post`);
    // It must still be useful — point at contact/pricing/help/status, not a dead end.
    assert.match(r, /contact|pricing|status|help|email/i, `${reason} must offer a next step`);
  }
  // A name, when present, is used.
  assert.match(degradedReply("error", "Sam"), /Sam/);
});

